package com.bank.onboard.service;

import java.util.logging.Logger;

// Counts ways to reach the top taking 1 or 2 steps (Fibonacci recurrence).
public class OnboardingPathService {
    private static final Logger log = Logger.getLogger(OnboardingPathService.class.getName());

    public long countWays(int steps) {
        if (steps <= 1) return 1;                   // one way to reach 0 or 1
        long prev2 = 1, prev1 = 1;                  // ways to reach steps 0 and 1
        for (int i = 2; i <= steps; i++) {
            long cur = prev1 + prev2;               // sum of previous two
            prev2 = prev1;
            prev1 = cur;                            // slide the window
        }
        final long r = prev1;
        log.info(() -> "Ways to climb " + steps + " = " + r);
        return prev1;
    }
}
