package com.bank.onboard;

import com.bank.onboard.service.OnboardingPathService;
import java.util.logging.Logger;

public class OnboardingPathApplication {
    private static final Logger log = Logger.getLogger(OnboardingPathApplication.class.getName());

    public static void main(String[] args) {
        OnboardingPathService service = new OnboardingPathService();
        int steps = 4;
        long ways = service.countWays(steps);
        log.info("Distinct onboarding sequences for " + steps + " steps: " + ways);
    }
}
